from __future__ import annotations
from typing import Sequence

def assemble_prefixes(bits: Sequence[int]) -> list[tuple[int, ...]]:
    if any(bit not in (0, 1) for bit in bits):
        raise ValueError("bits must be 0 or 1")
    data = tuple(bits)
    return [data[:n + 1] for n in range(len(data))]

def diagonal(stages: Sequence[tuple[int, ...]]) -> tuple[int, ...]:
    if any(len(stage) != n + 1 for n, stage in enumerate(stages)):
        raise ValueError("wrong stage sizes")
    if any(stages[n + 1][:-1] != stages[n] for n in range(len(stages) - 1)):
        raise ValueError("incoherent family")
    return tuple(stage[-1] for stage in stages)

if __name__ == "__main__":
    signal = (1, 0, 0, 1, 0, 1)
    stages = assemble_prefixes(signal)
    print(*stages, sep="\n")
    print("Recovered:", diagonal(stages))

from __future__ import annotations
from fractions import Fraction
from math import comb

def bernoulli_numbers(n: int) -> list[Fraction]:
    if n < 0:
        raise ValueError("n must be nonnegative")
    values = [Fraction(1)]
    for m in range(1, n + 1):
        total = sum(Fraction(comb(m + 1, k)) * values[k] for k in range(m))
        values.append(-total / Fraction(m + 1))
    return values

if __name__ == "__main__":
    values = bernoulli_numbers(12)
    for n, value in enumerate(values):
        check = sum(Fraction(comb(n + 1, k)) * values[k] for k in range(n + 1))
        print(f"B_{n} = {str(value):>5}; recurrence sum = {check}")

