from __future__ import annotations
from typing import Sequence

def reconstruct(stages: Sequence[tuple[int, ...]]) -> tuple[int, ...]:
    for n, stage in enumerate(stages):
        if len(stage) != n + 1:
            raise ValueError(f"stage {n} has the wrong length")
        if any(bit not in (0, 1) for bit in stage):
            raise ValueError("coordinates must lie in F_2")
        if n and stage[:-1] != stages[n - 1]:
            raise ValueError(f"coherence fails between stages {n-1} and {n}")
    return tuple(stage[-1] for stage in stages)

from __future__ import annotations
from typing import Sequence

def zero_extended_lift(stage: Sequence[int], final_length: int) -> list[tuple[int, ...]]:
    prefix = tuple(stage)
    if not prefix or any(x not in (0, 1) for x in prefix):
        raise ValueError("stage must be a nonempty Boolean vector")
    if final_length < len(prefix):
        raise ValueError("final_length is too small")
    sequence = prefix + (0,) * (final_length - len(prefix))
    return [sequence[:n + 1] for n in range(final_length)]

